CREATE TABLE IF NOT EXISTS content_types (code VARCHAR(40) PRIMARY KEY,name VARCHAR(80) NOT NULL,icon VARCHAR(12) NOT NULL,accent VARCHAR(24) NOT NULL DEFAULT 'amber',description VARCHAR(500) NOT NULL DEFAULT '',created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
